994	void LiaStarExtension::advanceStage(MainEnum& en, Node skolemDisjunct)
995	{
996	  // Open a new enumeration stage: a fresh guard that activates the previous
997	  // stage's constraints plus the negation of the newly covered cell, so the
998	  // current guard always activates `base and not(D_1) ... and not(D_k)` with
999	  // two constant-size lemmas per stage.
1000	  Node g = d_nm->mkDummySkolem("liastarEnumGuard", d_nm->booleanType());
1001	  g = d_astate.getValuation().ensureLiteral(g);
1002	  d_im.preferPhase(g, true);
1003	  addEnumLemma(g.impNode(en.guard));
1004	  addEnumLemma(g.impNode(skolemDisjunct.notNode()));
1005	  en.guard = g;
1006	}
