1038	void LiaStarExtension::mainSolverCheckStar(
1039	    Node literal, Node lambda, const std::map<Node, Node>& arithModel)
1040	{
1041	  // Main-solver lazy reduction: drive one refinement round for `literal`,
1042	  // enumerating the predicate's cells in the main solver instead of a
1043	  // dedicated subsolver. Stop refining once the literal has been fully
1044	  // reduced.
1045	  if (std::find(
1046	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
1047	      != d_processedStarTerms.end())
1048	  {
1049	    return;
1050	  }
1051	
1052	  bool seeded = d_mainEnums.find(lambda) != d_mainEnums.end();
1053	  MainEnum& en = getMainEnum(lambda);
1054	
1055	  // Catch up: open one stage per cone-disjunct discovered since the previous
1056	  // round (e.g. through another literal with the same lambda). The disjuncts
1057	  // are stored in bound-variable space, so map them to skolem space first.
1058	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& pairs =
1059	      d_lazyCones[lambda];
1060	  for (size_t i = en.negated; i < pairs.size(); i++)
1061	  {
1062	    Node disjunct = pairs[i].first;
1063	    if (!en.from.empty())
1064	    {
1065	      disjunct = disjunct.substitute(
1066	          en.from.begin(), en.from.end(), en.to.begin(), en.to.end());
1067	    }
1068	    advanceStage(en, disjunct);
1069	  }
1070	  en.negated = pairs.size();
1071	
1072	  if (!seeded)
1073	  {
1074	    // First round: the seed lemmas were only queued just now, so there is no
1075	    // assignment of the guard or the skolems to read yet. The driver lemma
1076	    // makes an unjustified literal activate the enumeration.
1077	    emitDriverLemma(literal, en);
1078	    d_im.doPendingLemmas();
1079	    return;
1080	  }
1081	
1082	  Valuation& val = d_astate.getValuation();
1083	  bool guardValue = false;
1084	  bool assigned = val.isSatLiteral(en.guard)
1085	                  && val.hasSatValue(en.guard, guardValue);
1086	  if (assigned && !guardValue && val.isFixed(en.guard))
1087	  {
1088	    // The negated stage guard is implied by the input assertions: the
1089	    // predicate conjoined with the negated disjuncts is unsatisfiable, so
1090	    // every cell of the predicate is covered by a cone and the encoding is
1091	    // exact (this is the analogue of the subsolver answering unsat).
1092	    processDisjunct(literal, d_false, /*complete=*/true);
1093	    return;
1094	  }
1095	  if (!assigned || !guardValue)
1096	  {
1097	    // No cell can be read this round. (Re-)emit the driver for the current
1098	    // stage: a model claiming the literal without certifying it cannot then
1099	    // be accepted, since the driver forces the stage guard in any such
1100	    // model, and the model-value shortcut in checkFullEffort accepts the
1101	    // certified ones.
1102	    emitDriverLemma(literal, en);
1103	    d_im.doPendingLemmas();
1104	    return;
1105	  }
1106	
1107	  // The stage guard is true: the skolems lie in a region of the predicate
1108	  // not covered by any cone. Read off the cell containing them.
1109	  Node disjunct = getModelDisjunct(en, arithModel);
1110	  Trace("liastar-ext") << "main-solver disjunct: " << disjunct << std::endl;
1111	  if (disjunct.isNull())
1112	  {
1113	    // some atom had no model value; try again next round
1114	    emitDriverLemma(literal, en);
1115	    d_im.doPendingLemmas();
1116	    return;
1117	  }
1118	  // Guard against re-harvesting a known cell (its negation lemma may not
1119	  // have reached the solver before this model was produced).
1120	  for (const auto& pair : pairs)
1121	  {
1122	    if (pair.first == disjunct)
1123	    {
1124	      emitDriverLemma(literal, en);
1125	      d_im.doPendingLemmas();
1126	      return;
1127	    }
1128	  }
1129	  // Open the stage that excludes the new cell, so the continuing search
1130	  // moves the skolems to another cell.
1131	  Node skolemDisjunct = disjunct;
1132	  if (!en.from.empty())
1133	  {
1134	    skolemDisjunct = skolemDisjunct.substitute(
1135	        en.from.begin(), en.from.end(), en.to.begin(), en.to.end());
1136	  }
1137	  advanceStage(en, skolemDisjunct);
1138	  // Turn the cell into a cone and emit the (tentative) reduction lemma.
1139	  // `processDisjunct` appends the cone to `d_lazyCones[lambda]`, which the
1140	  // stage above has already negated, and updates the star
1141	  // under-approximation that the new driver lemma references.
1142	  processDisjunct(literal, disjunct, /*complete=*/false);
1143	  en.negated = pairs.size();
1144	  emitDriverLemma(literal, en);
1145	  d_im.doPendingLemmas();
1146	}
