1148	void LiaStarExtension::lazyHilbert(Node literal, Subsolver& sub)
1149	{
1150	  // One lazy refinement round for `literal`. Ask the subsolver for a model in a
1151	  // region of p not yet covered by a cone, read off the convex cell containing
1152	  // it, and hand it to `processDisjunct` for the cone and lemma generation.
1153	  Node variables = literal[0][0];
1154	  Trace("liastar-lazy") << "lazyHilbert::variables:" << variables << std::endl;
1155	
1156	  traceSmtPreamble(variables);
1157	
1158	  // Check the subsolver and read off the disjunct (the cell of the predicate)
1159	  // containing the model. The subsolver already has the predicate and the
1160	  // negations of all previously discovered cone-disjuncts asserted, so the
1161	  // model lies in a region of the predicate not yet covered by any cone.
1162	  Node disjunct = LiaStarUtils::getDisjunct(
1163	      sub.base, sub.from, sub.to, &d_env, sub.engine.get());
1164	  // `getDisjunct` returns false when no region of `formula` is left uncovered,
1165	  // i.e. every disjunct of the predicate already has a cone. At that point the
1166	  // cone encoding is exact and we can assert the full equivalence.
1167	  bool complete = disjunct == d_false;
1168	  processDisjunct(literal, disjunct, complete);
1169	}
